PRAGMA foreign_keys=ON;
CREATE TABLE Users(Id INTEGER PRIMARY KEY,Username TEXT NOT NULL UNIQUE,PasswordHash TEXT NOT NULL,Role TEXT NOT NULL,CreatedAt TEXT NOT NULL);
CREATE TABLE Documents(Id INTEGER PRIMARY KEY,TrackingNumber TEXT NOT NULL UNIQUE,Title TEXT NOT NULL,Department TEXT NOT NULL,Status TEXT NOT NULL,CreatedById INTEGER NOT NULL REFERENCES Users(Id),CreatedAt TEXT NOT NULL,UpdatedAt TEXT NOT NULL);
CREATE TABLE Events(Id INTEGER PRIMARY KEY,TrackedDocumentId INTEGER NOT NULL REFERENCES Documents(Id),FromStatus TEXT NOT NULL,ToStatus TEXT NOT NULL,Notes TEXT NOT NULL,PerformedById INTEGER NOT NULL REFERENCES Users(Id),CreatedAt TEXT NOT NULL);
